  'b.first': ['A wild <b>{name}</b> jumps out of the crater!', 'Z krateru wyskakuje dziki <b>{name}</b>!'],
  'in.choose': ['I choose {name}!', 'Wybieram: {name}!'], 'ui.save': ['Save', 'Zapisz'], 'pf.look': ['Change look', 'Zmień wygląd'],
  'tut.go': ['Look, a wild Orbling! Tap the one under the arrow and catch it!', 'Patrz, dziki Orbling! Kliknij tego pod strzałką i złap go!'],
  'tut.nudge': ['Over there, under the arrow! Tap that Orbling.', 'Tam, pod strzałką! Kliknij tego Orblinga.'],
  'tut.first': ['That one later! First the Orbling under the arrow.', 'Tego później! Najpierw Orbling pod strzałką.'],
  'tut.later': ['Go catch your first Orbling, the one under the arrow. Then come back and battle me!', 'Najpierw złap swojego pierwszego Orblinga, tego pod strzałką. Potem wróć i zmierz się ze mną!'],
