/* codex descriptions */
L({
  'd.fluffire': ['A fluffy lamb whose wool is always warm. It sneezes tiny sparks when excited.', 'Puchate jagnię o zawsze ciepłej wełnie. Gdy się ekscytuje, kicha małymi iskierkami.'],
  'd.blazeram': ['Its curled horns glow red-hot. It practices for battle by headbutting boulders.', 'Jego zakręcone rogi rozgrzewają się do czerwoności. Trenuje, trykając głazy.'],
  'd.ignaram': ['It rises onto its hind legs to fight, wrapped in a mantle of living flame. Its horns can split boulders.', 'Do walki staje na tylnych nogach, owinięty płaszczem z żywego płomienia. Rogami rozłupuje głazy.'],
  'd.mossmoo': ['A gentle calf with a sprout on its head. It naps in sunny meadows to help its moss grow.', 'Łagodne cielątko z kiełkiem na głowie. Drzemie na słonecznych łąkach, by rósł mu mech.'],
  'd.bouldox': ['Stone plates cover its back. Once it starts charging, not even a wall can stop it.', 'Kamienne płyty pokrywają jego grzbiet. Gdy ruszy do szarży, nie zatrzyma go nawet mur.'],
  'd.gaiaurus': ['A whole mountain grows on its back — snowy peaks, moss and a lone tree. Birds nest there without fear.', 'Na grzbiecie wyrosła mu cała góra — ośnieżone szczyty, mech i samotne drzewko. Ptaki zakładają tam gniazda bez obaw.'],
  'd.zapsy': ['Two-toned and full of static. It can never decide which mood to follow.', 'Dwukolorowy i naładowany elektrycznością. Nie potrafi zdecydować, któremu nastrojowi ulec.'],
  'd.twinbolt': ['Its two halves argue constantly, but they strike as one when danger comes.', 'Jego dwie połówki ciągle się kłócą, ale w obliczu zagrożenia uderzają jak jedna.'],
  'd.geminova': ['A storm imp of twin stars. It flies on lightning wings, and its crystal horn crackles with thunder.', 'Burzowy chochlik z bliźniaczych gwiazd. Lata na skrzydłach z błyskawic, a jego kryształowy róg trzeszczy od grzmotów.'],
  'd.clawby': ['A cheerful crab that waves its claws at everyone it meets.', 'Wesoły krab, który macha szczypcami do każdego, kogo spotka.'],
  'd.shellsnap': ['Its spiky shell is harder than steel. It snaps at anything shiny.', 'Jego kolczasta skorupa jest twardsza od stali. Chwyta wszystko, co błyszczy.'],
  'd.moontide': ['It carries a crescent moon for a shell and commands the tides with one giant claw.', 'Za skorupę nosi sierp księżyca, a jednym olbrzymim szczypcem rozkazuje przypływom.'],
  'd.sunkit': ['A playful cub with a flickering tail. It loves chasing its own sparks.', 'Figlarne lwiątko z migoczącym ogonem. Uwielbia gonić własne iskry.'],
  'd.pridefang': ['Its mane bursts into flame when it roars. It never backs down from a challenge.', 'Jego grzywa staje w płomieniach, gdy ryczy. Nigdy nie cofa się przed wyzwaniem.'],
  'd.solmane': ['Its blazing mane shines like a second sun. All of Ember Isle bows to its roar.', 'Jego płonąca grzywa świeci jak drugie słońce. Cała Wyspa Żaru kłania się jego rykowi.'],
  'd.budlet': ['A shy sprout Orbling. Its bud opens only for friends it truly trusts.', 'Nieśmiały kiełkowy Orbling. Jego pąk otwiera się tylko przed prawdziwymi przyjaciółmi.'],
  'd.petalina': ['It dances among flowers and leaves a sweet scent wherever it flutters.', 'Tańczy wśród kwiatów i zostawia słodki zapach wszędzie, gdzie przefrunie.'],
  'd.floravelle': ['A garden dryad in a dress of petals. Wilted plants bloom again wherever she dances.', 'Ogrodowa driada w sukience z płatków. Zwiędłe rośliny rozkwitają tam, gdzie zatańczy.'],
  'd.breezle': ['A tiny bird that rides the breeze. It chirps a different tune for every wind.', 'Malutki ptaszek, który szybuje na wietrze. Dla każdego wiatru ćwierka inną melodię.'],
  'd.gustwing': ['It keeps perfect balance even in a hurricane, gliding through storms with ease.', 'Zachowuje idealną równowagę nawet w huraganie i z łatwością szybuje przez burze.'],
  'd.libratross': ['It never lands. It carries golden scales through the sky and keeps the winds in balance.', 'Nigdy nie ląduje. Niesie przez niebo złotą wagę i trzyma wiatry w równowadze.'],
  'd.stingle': ['Its stinger is soft as a feather when young, but it acts tough anyway.', 'W młodości jego żądło jest miękkie jak piórko, ale i tak zgrywa twardziela.'],
  'd.venomire': ['It lurks in tide pools at dusk. Its sting leaves a numbing chill.', 'Czai się o zmierzchu w pływowych sadzawkach. Jego żądło zostawia paraliżujący chłód.'],
  'd.abyssting': ['A scorpion knight of the deep. It stands tall, pincers raised, its glowing sting poised over its head.', 'Skorpioni rycerz z głębin. Stoi wyprostowany z uniesionymi szczypcami, a świecące żądło trzyma nad głową.'],
  'd.cinderfawn': ['A spotted fawn with ember-warm fur. It leaps over campfires for fun.', 'Cętkowany jelonek o futrze ciepłym jak żar. Dla zabawy przeskakuje nad ogniskami.'],
  'd.emberstag': ['Tiny flames dance on its antlers. It is said to guide lost travelers home.', 'Na jego porożu tańczą małe płomienie. Podobno prowadzi zagubionych wędrowców do domu.'],
  'd.meteorhorn': ['It rears up before it charges. Its antlers burn and it leaves a comet trail across the sky.', 'Przed szarżą staje dęba. Jego poroże płonie, a za nim ciągnie się po niebie ogon komety.'],
  'd.goatlet': ['A curious kid that climbs anything. It munches on crystals as a snack.', 'Ciekawskie koźlę, które wspina się na wszystko. Na przekąskę chrupie kryształy.'],
  'd.cragoat': ['It leaps from cliff to cliff without fear. Its horns can crack granite.', 'Bez strachu skacze z urwiska na urwisko. Jego rogi kruszą granit.'],
  'd.peakhorn': ['It stands on its own little floating isle and rides it from peak to peak, horns ringing in the wind.', 'Stoi na własnej latającej wysepce i przemierza na niej szczyty, a jego rogi dzwonią na wietrze.'],
  'd.nimbub': ['A fluffy cloud Orbling that cries tiny raindrops when it laughs.', 'Puchaty chmurkowy Orbling, który płacze kropelkami deszczu, gdy się śmieje.'],
  'd.nimbolt': ['A grumpy storm cloud. Poke it and you\'ll get a shocking surprise!', 'Zrzędliwa chmura burzowa. Szturchnij ją, a czeka cię porażająca niespodzianka!'],
  'd.tempestar': ['A sky dragon made of thunderclouds. Its roar is the sound of rolling thunder.', 'Niebiański smok z chmur burzowych. Jego ryk brzmi jak przetaczający się grzmot.'],
  'd.finnip': ['A giggly fish with frilly gills. It can hop on land for a short while.', 'Chichotliwa rybka z falbaniastymi skrzelami. Przez chwilę potrafi skakać po lądzie.'],
  'd.koiwhirl': ['It swims in graceful spirals. Seeing one is said to bring good luck.', 'Pływa w pełnych gracji spiralach. Podobno jej widok przynosi szczęście.'],
  'd.pisceidon': ['A sea dragon that guards the ocean\'s secrets. It can summon whirlpools.', 'Morski smok strzegący tajemnic oceanu. Potrafi przywoływać wiry.'],
  'd.chrysaries': ['The golden ram of the Aries stars. It flies on white wings, and its fleece is said to grant courage.', 'Złoty baran z gwiazd Barana. Lata na białych skrzydłach, a jego runo podobno dodaje odwagi.'],
  'd.terrataur': ['The Taurus titan walks on two legs, wrapped in moss. Mountains rise wherever it stamps its hooves.', 'Tytan Byka chodzi na dwóch nogach, okryty mchem. Góry wyrastają wszędzie, gdzie tupnie kopytami.'],
  'd.castorlux': ['The twin stars of Gemini: two spirits who always hold hands. When they part, the night goes dark.', 'Bliźniacze gwiazdy Bliźniąt: dwa duszki, które zawsze trzymają się za ręce. Kiedy się rozdzielą, noc gaśnie.'],
  'd.lunacrest': ['The moon crab of Cancer. It floats before the full moon and pulls the tides of every sea.', 'Księżycowy krab Raka. Unosi się na tle pełni i przyciąga przypływy wszystkich mórz.'],
  'd.regulion': ['The king of Leo, winged and crowned with a sunburst. Its roar can light up the night.', 'Skrzydlaty król Lwa w koronie z promieni słońca. Jego ryk potrafi rozświetlić noc.'],
  'd.spicaria': ['The harvest goddess of Virgo floats on a dress of golden petals. Wherever she passes, fields turn golden.', 'Bogini żniw z gwiazdozbioru Panny unosi się w sukni ze złotych płatków. Gdzie przeleci, pola stają się złote.'],
  'd.equinyx': ['The bird of Libra flies before a disc that is half sun and half night, keeping the two in balance.', 'Ptak Wagi lata na tle tarczy, która jest w połowie słońcem, a w połowie nocą, i trzyma je w równowadze.'],
  'd.antarex': ['The crimson heart of Scorpio. It flies on dragon wings, and its glow burns brighter than any star.', 'Szkarłatne serce Skorpiona. Lata na smoczych skrzydłach, a jego blask płonie jaśniej niż jakakolwiek gwiazda.'],
  'd.sagittaris': ['The centaur archer of Sagittarius. It never misses — its arrows are tipped with starfire.', 'Centaur-łucznik ze Strzelca. Nigdy nie chybia — jego strzały mają groty z gwiezdnego ognia.'],
  'd.aegoros': ['The sea-goat of Capricorn: a goat in front, a fish behind. It swims through the sky as if it were the sea.', 'Morski koziorożec: z przodu koza, z tyłu ryba. Pływa po niebie, jakby to było morze.'],
  'd.sadalmir': ['The water bearer of Aquarius, a genie on a curl of cloud. It pours starlight rain from its golden urn.', 'Nosiciel wody z Wodnika, dżin na kłębie chmury. Ze złotego dzbana leje deszcz gwiezdnego światła.'],
  'd.alreshia': ['The twin koi of Pisces, bound by a ribbon of stars. It swims through dreams.', 'Bliźniacze koi Ryb połączone wstęgą gwiazd. Pływa przez sny.'],
});

