  'st.title': ['Requests', 'Prośby postaci'],
  'st.new': ['{name} has a request for you! (Quests)', '{name} ma do ciebie prośbę! (Zadania)'],
  'st.ready': ['Done! Go and see them.', 'Gotowe! Odwiedź tę postać.'],
  'hud.q_story': ['has a request', 'ma prośbę'],
  'st.tim.a1': ['Good battle! Can I tell you a secret? A Sunkit lives on Clover Meadow — but I\'ve only ever seen the tip of its tail.', 'Dobra walka! Zdradzę ci sekret: na Koniczynowej Łące mieszka Sunkit — ale widziałem tylko czubek jego ogona.'],
  'st.tim.a2': ['If you ever catch one, will you show me? I\'d love to see it up close!', 'Jeśli kiedyś go złapiesz, pokażesz mi? Tak bardzo chcę go zobaczyć z bliska!'],
  'st.tim.w': ['Still no Sunkit? It\'s shy — look around Clover Meadow!', 'Nadal bez Sunkita? Jest nieśmiały — rozejrzyj się po Koniczynowej Łące!'],
  'st.tim.b1': ['Whoa, a real Sunkit! It\'s even cuter than I imagined!', 'Ojej, prawdziwy Sunkit! Jest jeszcze słodszy, niż myślałem!'],
  'st.tim.b2': ['Here — take my old tent for your Base. Camping under the stars is the best!', 'Proszę — weź mój stary namiot do swojej Bazy. Nocowanie pod gwiazdami jest najlepsze!'],
  'st.tim.q': ['Show Tim a Sunkit (or its evolution)', 'Pokaż Timowi Sunkita (albo jego ewolucję)'],
  'st.rex.a1': ['Mrrow... the big one got away again. A Koiwhirl, shimmering like a rainbow!', 'Mrrau... znowu uciekła mi ta wielka. Koiwhirl, mieniący się jak tęcza!'],
  'st.rex.a2': ['Nobody believes me. Catch one and prove I\'m no fibber, would you?', 'Nikt mi nie wierzy. Złap jednego i udowodnij, że nie zmyślam, dobrze?'],
  'st.rex.w': ['Koiwhirls love the water — try Seashell Shore, or the isles further out.', 'Koiwhirle kochają wodę — spróbuj na Muszelkowym Brzegu albo na dalszych wyspach.'],
  'st.rex.b1': ['That\'s it! That\'s the one! Now they\'ll all have to believe me!', 'To on! To ten sam! Teraz wszyscy muszą mi uwierzyć!'],
  'st.rex.b2': ['Take this little lighthouse. It kept me company on long nights of fishing.', 'Weź tę małą latarnię. Dotrzymywała mi towarzystwa w długie noce na rybach.'],
  'st.rex.q': ['Show Rex a Koiwhirl (or its evolution)', 'Pokaż Rexowi Koiwhirla (albo jego ewolucję)'],
  'st.jax.a1': ['Umbra says Orblings are just tools... but mine looked so sad when we lost.', 'Umbra mówi, że Orblingi to tylko narzędzia... ale moje były takie smutne, gdy przegraliśmy.'],
  'st.jax.a2': ['Yours look happy. How? Show me an Orbling that truly trusts you — two hearts of friendship!', 'Twoje wyglądają na szczęśliwe. Jak to robisz? Pokaż mi Orblinga, który ci ufa — dwa serca przyjaźni!'],
  'st.jax.w': ['Pet them at your Base, battle together... friendship takes time, right?', 'Głaszcz je w Bazie, walczcie razem... przyjaźń wymaga czasu, prawda?'],
  'st.jax.b1': ['So that\'s what trust looks like... I\'m leaving Team Eclipse. For real.', 'Więc tak wygląda zaufanie... Odchodzę z Zespołu Zaćmienia. Naprawdę.'],
  'st.jax.b2': ['Take my campfire. Tell stories around it with your Orblings — I will with mine.', 'Weź moje ognisko. Opowiadaj przy nim historie swoim Orblingom — ja też będę.'],
  'st.jax.q': ['Show Jax an Orbling with ♥♥ friendship', 'Pokaż Jaxowi Orblinga z przyjaźnią ♥♥'],
  'st.ivan.a1': ['Fascinating! My research asks: are Orblings from eggs special? I need a real hatching to observe.', 'Fascynujące! Moje badania pytają: czy Orblingi z jaj są wyjątkowe? Potrzebuję prawdziwego wyklucia.'],
  'st.ivan.a2': ['Hatch an egg in the Hatchery at your Base and tell me all about it!', 'Wykluj jajo w Wylęgarni swojej Bazy i opowiedz mi o wszystkim!'],
  'st.ivan.w': ['Eggs hatch after battles you win. Patience — and many battles!', 'Jaja wykluwają się po wygranych walkach. Cierpliwości — i dużo walk!'],
  'st.ivan.b1': ['Great potential, exactly as my theory said! My thanks!', 'Świetny potencjał, zupełnie jak przewidywała moja teoria! Dziękuję!'],
  'st.ivan.b2': ['Here is my spare telescope — and an egg for your next experiment.', 'Oto mój zapasowy teleskop — i jajo na kolejny eksperyment.'],
  'st.ivan.q': ['Hatch an egg for Ivan\'s research', 'Wykluj jajo do badań Ivana'],
  'st.jett.a1': ['BEEP. Weather station: 90% built. Missing part: star shards.', 'BIP. Stacja pogody: zbudowana w 90%. Brakuje: gwiezdnych okruchów.'],
  'st.jett.a2': ['Collect 10 star shards for me. They sparkle on the ground of every isle. BEEP-BOOP.', 'Zbierz dla mnie 10 gwiezdnych okruchów. Błyszczą na ziemi każdej wyspy. BIP-BUP.'],
  'st.jett.w': ['Shards collected: not enough yet. Keep your eyes on the ground!', 'Zebrane okruchy: jeszcze za mało. Patrz pod nogi!'],
  'st.jett.b1': ['Shards received. Station: 100%. Forecast: sunny, with a chance of friendship. BEEP!', 'Okruchy odebrane. Stacja: 100%. Prognoza: słonecznie, z szansą na przyjaźń. BIP!'],
  'st.jett.b2': ['I built a second one for your Base. Weather reports free of charge!', 'Zbudowałem drugą dla twojej Bazy. Prognozy za darmo!'],
  'st.jett.q': ['Collect 10 star shards for Jett', 'Zbierz 10 gwiezdnych okruchów dla Jetta'],
